'use client'

import { useEffect, useMemo, useState } from 'react'
import Link from 'next/link'
import { Activity, AlertTriangle, ArrowLeft, ArrowRight, Box, CheckCircle2, Circle, Clock3, Download, FileText, Loader2, MapPin, PackageCheck, PackageSearch, Pencil, Plus, Send, ShieldCheck, Star, Trash2, Truck, XCircle } from 'lucide-react'
import { toast } from 'sonner'
import { DashboardShell } from '@/components/dashboard-shell'
import { TrackingSearch } from '@/components/tracking-search'
import { customerNav, businessNav } from '@/lib/navigation'
import { customerServiceLabel } from '@/lib/customer-service-label'
import { documentCategoryLabel } from '@/lib/documents'
import { InvoiceActions } from '@/components/invoice-actions'

type Quote = any; type Shipment = any; type Address = any; type Ticket = any
export function CustomerPortal({ base, section, itemId, business = false }: { base: '/customer'|'/business'; section: string; itemId?: string; business?: boolean }) {
  const [quotes, setQuotes] = useState<Quote[]>([]); const [shipments, setShipments] = useState<Shipment[]>([]); const [addresses, setAddresses] = useState<Address[]>([]); const [tickets, setTickets] = useState<Ticket[]>([]); const [loading, setLoading] = useState(true); const [deciding, setDeciding] = useState(false); const [editing, setEditing] = useState<Address | null>(null)
  const nav = business ? businessNav : customerNav; const activeHref = `${base}${section === 'dashboard' ? '' : `/${section}`}`; const selected = quotes?.find?.((item: Quote) => item?.id === itemId) ?? null
  async function load() { setLoading(true); try { const [q,s,a,t] = await Promise.all(['/api/quotes','/api/shipments','/api/addresses','/api/support'].map(async (url:string) => { const response=await fetch(url); return response?.json?.().catch?.(() => ({})) ?? {} })); setQuotes(q?.quotes ?? []); setShipments(s?.shipments ?? []); setAddresses(a?.addresses ?? []); setTickets(t?.tickets ?? []) } catch (error: unknown) { console.error(error); toast?.error?.('Unable to refresh workspace data.') } finally { setLoading(false) } }
  useEffect(() => { void load() }, [])
  const stats = useMemo(() => [{label:'Active Quotes',value:quotes?.filter?.((q:Quote)=>['PENDING_REVIEW','QUOTED'].includes(q?.status ?? ''))?.length ?? 0,icon:PackageSearch,color:'bg-blue-50 text-blue-700'},{label:'Active Shipments',value:shipments?.filter?.((s:Shipment)=>!['DELIVERED','CANCELLED'].includes(s?.status ?? ''))?.length ?? 0,icon:Truck,color:'bg-amber-50 text-amber-700'},{label:'Delivered',value:shipments?.filter?.((s:Shipment)=>s?.status==='DELIVERED')?.length ?? 0,icon:PackageCheck,color:'bg-green-50 text-green-700'},{label:'Pending Review',value:quotes?.filter?.((q:Quote)=>q?.status==='PENDING_REVIEW')?.length ?? 0,icon:Clock3,color:'bg-purple-50 text-purple-700'}], [quotes, shipments])
  async function decide(id:string,status:'ACCEPTED'|'REJECTED',optionId?:string|null) { if(deciding) return; setDeciding(true); try { const response=await fetch(`/api/quotes/${id}`,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({status,...(optionId?{optionId}:{})})}); const data=await response?.json?.().catch?.(() => ({})) ?? {}; if(!response?.ok) throw new Error(data?.error ?? 'Unable to update quote.'); toast?.success?.(`Quotation ${status?.toLowerCase?.() ?? ''}.`); await load() } catch(error:unknown){console.error(error);toast?.error?.(error instanceof Error?error?.message ?? 'Unable to update quote.':'Unable to update quote.')} finally { setDeciding(false) } }
  async function requestUpdate(id:string) { if(deciding) return; setDeciding(true); try { const response=await fetch(`/api/quotes/${id}/request-update`,{method:'POST',headers:{'Content-Type':'application/json'}}); const data=await response?.json?.().catch?.(() => ({})) ?? {}; if(!response?.ok) throw new Error(data?.error ?? 'Unable to submit request.'); toast?.success?.('Request sent — our team will send you an updated quotation shortly.'); await load() } catch(error:unknown){console.error(error);toast?.error?.(error instanceof Error?error?.message ?? 'Unable to submit request.':'Unable to submit request.')} finally { setDeciding(false) } }
  const title = section === 'dashboard' ? (business ? 'Business Dashboard' : 'Dashboard') : section?.split?.('-')?.join?.(' ')?.replace?.(/\b\w/g,(value:string)=>value?.toUpperCase?.() ?? value) ?? 'Workspace'
  return <DashboardShell title={title} nav={nav} activeHref={activeHref}>{loading ? <Loading /> : <div className="mx-auto max-w-[1200px]">{section === 'dashboard' ? <DashboardHome stats={stats} quotes={quotes} base={base} /> : null}{section === 'quotes' && !itemId ? <QuotesTable quotes={quotes} base={base} title="My Quotes" /> : null}{section === 'quotes' && itemId ? <QuoteDetail quote={selected} onDecide={decide} onRequestUpdate={requestUpdate} deciding={deciding} /> : null}{section === 'shipments' && !itemId ? <ShipmentsList shipments={shipments} base={base} /> : null}{section === 'shipments' && itemId ? <ShipmentDetail shipment={shipments?.find?.((s:Shipment)=>s?.id===itemId) ?? null} base={base} reload={load} /> : null}{section === 'tracking' ? <div className="mx-auto max-w-3xl"><TrackingSearch /></div> : null}{['addresses','address-book'].includes(section) ? <AddressBook addresses={addresses} editing={editing} setEditing={setEditing} reload={load} enhanced={business} /> : null}{section === 'support' ? <SupportDesk tickets={tickets} reload={load} /> : null}{section === 'documents' || section === 'saved-documents' ? <Documents quotes={quotes} /> : null}{section === 'imports' ? <QuotesTable quotes={quotes?.filter?.((q:Quote)=>q?.direction==='IMPORT') ?? []} base={base} title="Import Shipments" /> : null}{section === 'exports' ? <QuotesTable quotes={quotes?.filter?.((q:Quote)=>q?.direction==='EXPORT') ?? []} base={base} title="Export Shipments" /> : null}</div>}</DashboardShell>
}
function Loading(){return <div className="flex min-h-[50vh] items-center justify-center"><Loader2 className="h-7 w-7 animate-spin text-green-600" /></div>}
function DashboardHome({stats,quotes,base}:{stats:any[];quotes:Quote[];base:string}){return <div className="grid gap-6"><div><p className="section-kicker">Operations at a glance</p><h2 className="text-2xl font-bold tracking-tight text-[#0A1628]">Your shipment workspace</h2><p className="mt-2 text-sm text-slate-500">Monitor active work and move quickly to your next task.</p></div><div className="grid grid-cols-2 gap-4 xl:grid-cols-4">{stats?.map?.((item:any)=>{const Icon=item?.icon??Activity;return <article key={item?.label??''} className="rounded-xl bg-white p-5 shadow-[var(--shadow-sm)]"><span className={`flex h-9 w-9 items-center justify-center rounded-lg ${item?.color ?? ''}`}><Icon className="h-5 w-5" /></span><p className="mt-5 text-2xl font-bold text-[#0A1628]">{item?.value ?? 0}</p><p className="mt-1 text-xs font-medium text-slate-500">{item?.label ?? ''}</p></article>}) ?? null}</div><div className="grid gap-5 lg:grid-cols-[1fr_280px]"><QuotesTable quotes={(quotes ?? []).slice?.(0,5) ?? []} base={base} title="Recent Quotes" compact /><div className="rounded-xl bg-[#0A1628] p-6 text-white shadow-[var(--shadow-md)]"><Plus className="h-7 w-7 text-green-400" /><h3 className="mt-5 text-lg font-bold">Ready to ship?</h3><p className="mt-2 text-sm leading-6 text-slate-300">Create a complete request and receive a manually reviewed quotation.</p><Link href="/quote/new" className="btn-primary mt-6 w-full">New quote <ArrowRight className="h-4 w-4" /></Link></div></div></div>}
function QuotesTable({quotes,base,title,compact=false}:{quotes:Quote[];base:string;title:string;compact?:boolean}){return <section className="overflow-hidden rounded-xl bg-white shadow-[var(--shadow-sm)]"><div className="flex items-center justify-between p-5"><div><h2 className="font-bold text-[#0A1628]">{title ?? ''}</h2><p className="mt-1 text-xs text-slate-500">{quotes?.length ?? 0} records</p></div>{!compact?<Link href="/quote/new" className="btn-primary min-h-9 px-3 py-1.5"><Plus className="h-4 w-4" /> New quote</Link>:null}</div><div className="overflow-x-auto"><table className="w-full min-w-[680px] text-left text-sm"><thead className="bg-slate-50 text-[10px] uppercase tracking-wider text-slate-500"><tr><th className="px-5 py-3">Reference</th><th className="px-5 py-3">Route</th><th className="px-5 py-3">Service</th><th className="px-5 py-3">Status</th><th className="px-5 py-3"></th></tr></thead><tbody className="divide-y divide-slate-100">{quotes?.map?.((q:Quote)=><tr key={q?.id ?? ''} className="hover:bg-slate-50"><td className="px-5 py-4 font-mono text-xs font-bold text-[#0A1628]">{q?.reference ?? ''}</td><td className="px-5 py-4 text-slate-600">{q?.senderJson?.city ?? '—'} → {q?.receiverJson?.city ?? '—'}</td><td className="px-5 py-4 text-xs text-slate-500">{format(q?.serviceType)}</td><td className="px-5 py-4"><Status value={q?.status ?? ''} /></td><td className="px-5 py-4 text-right"><Link href={`${base}/quotes/${q?.id ?? ''}`} className="inline-flex items-center gap-1 font-semibold text-green-700">View <ArrowRight className="h-3.5 w-3.5" /></Link></td></tr>) ?? null}{(quotes?.length ?? 0)===0?<tr><td colSpan={5} className="px-5 py-10 text-center text-slate-400">No quotes found.</td></tr>:null}</tbody></table></div></section>}
function QuoteDetail({quote,onDecide,onRequestUpdate,deciding=false}:{quote:Quote|null;onDecide:(id:string,status:'ACCEPTED'|'REJECTED',optionId?:string|null)=>void;onRequestUpdate:(id:string)=>void;deciding?:boolean}){const offers:any[]=Array.isArray(quote?.offers)?quote?.offers:[];const multi=offers.length>1;const preselected=(offers.find((o:any)=>o?.isSelected)?.optionId) ?? '';const [pick,setPick]=useState<string>(String(preselected ?? ''));if(!quote)return <Empty text="Quote not found."/>;const quotation:any=quote?.adminQuotation;const q:any=quote;const decidable=['SENT','APPROVED'].includes(String(quotation?.status ?? ''));const expired=!!quotation?.expired;const wc=q?.whatChanged;const needsReview=!!q?.needsReapproval;const history=q?.quotationHistory ?? [];return <div className="grid gap-5 lg:grid-cols-[1fr_340px]"><section className="rounded-xl bg-white p-6 shadow-[var(--shadow-sm)]"><div className="flex flex-wrap items-start justify-between gap-3"><div><p className="font-mono text-xs font-bold text-green-700">{quote?.reference ?? ''}</p><h2 className="mt-2 text-2xl font-bold text-[#0A1628]">{format(quote?.contentsType)}</h2></div><Status value={quote?.status ?? ''}/></div>{['ACCEPTED','BOOKED'].includes(quote?.status ?? '')?<div className="mt-6"><BookingSteps quote={quote}/></div>:null}<div className="mt-7 grid gap-4 rounded-lg bg-slate-50 p-5 sm:grid-cols-3"><Info label="Route" value={`${quote?.senderJson?.city ?? '—'}, ${quote?.senderJson?.country ?? ''} → ${quote?.receiverJson?.city ?? '—'}, ${quote?.receiverJson?.country ?? ''}`} /><Info label="Shipment" value={`${quote?.pieces ?? 0} pc · ${quote?.weightKg ?? 0} kg`} /><Info label="Incoterms" value={quote?.incoterms ?? '—'} /><Info label="Service category" value={quote?.serviceCategory?format(quote?.serviceCategory):'—'} /><Info label="Preferred service" value={quote?.customerCarrierPreference ? customerServiceLabel(quote?.customerCarrierPreference) : 'No preference'} /></div>{quote?.calculation && quote?.status!=='PENDING_REVIEW'?<div className="mt-6 rounded-lg border border-slate-200 p-5"><p className="label">Chargeable weight summary</p><div className="mt-3 grid gap-4 sm:grid-cols-3"><Info label="Actual weight" value={`${money(quote?.calculation?.totalActualWeight)} kg`} /><Info label="Volumetric weight" value={`${money(quote?.calculation?.totalVolumetricWeight)} kg`} /><Info label="Chargeable weight" value={`${money(quote?.calculation?.totalChargeableWeight)} kg`} /></div>{quotation?.serviceLabel?<p className="mt-4 text-sm text-slate-600">Final service: <span className="font-semibold text-[#0A1628]">{quotation?.serviceLabel}</span></p>:null}<p className="mt-2 text-[11px] text-slate-400">Chargeable weight is the greater of the actual and volumetric weight, per international courier standards.</p></div>:null}<div className="mt-7 grid gap-5 sm:grid-cols-2"><Party title="Sender" data={quote?.senderJson}/><Party title="Receiver" data={quote?.receiverJson}/></div>{quote?.specialInstructions?<div className="mt-6 rounded-lg bg-amber-50 p-4"><p className="label">Special instructions</p><p className="text-sm text-amber-900">{quote?.specialInstructions ?? ''}</p></div>:null}</section><aside className="grid content-start gap-5"><BookingCta quote={quote}/><div className="rounded-xl bg-white p-6 shadow-[var(--shadow-md)]"><h3 className="font-bold text-[#0A1628]">Quotation</h3>{quotation && quote?.status!=='PENDING_REVIEW'?<div className="mt-5">{needsReview&&decidable?<div className="mb-4 rounded-lg border border-amber-200 bg-amber-50 p-4"><p className="flex items-center gap-2 text-sm font-semibold text-amber-900"><AlertTriangle className="h-4 w-4"/> Updated quote — please review</p><p className="mt-1 text-xs leading-5 text-amber-800">Your quotation has been updated. Please review the details below and accept or decline the updated quote.</p></div>:null}{multi&&decidable&&!expired?<div><p className="text-xs font-semibold text-slate-500">Choose your service option</p><div className="mt-3 grid gap-2">{offers.map((o:any)=>{const val=String(o?.optionId ?? '');const active=pick===val;return <button key={val||'primary'} type="button" onClick={()=>setPick(val)} className={`flex items-center justify-between gap-3 rounded-lg border p-3 text-left transition ${active?'border-green-600 bg-green-50 ring-1 ring-green-600':'border-slate-200 hover:border-slate-300'}`}><div className="min-w-0"><p className="text-sm font-semibold text-[#0A1628]">{o?.serviceLabel ?? 'Service'}</p>{o?.finalTransitTime?<p className="mt-0.5 text-xs text-slate-500">{o?.finalTransitTime}</p>:null}</div><div className="flex shrink-0 items-center gap-2"><span className="text-lg font-bold text-[#0A1628]">{sym(o?.currency)}{money(o?.finalPrice)}</span><span className={`flex h-4 w-4 items-center justify-center rounded-full border ${active?'border-green-600 bg-green-600 text-white':'border-slate-300'}`}>{active?<CheckCircle2 className="h-3 w-3"/>:null}</span></div></button>})}</div></div>:<><p className="text-xs text-slate-500">Final selling price</p><p className="mt-1 text-3xl font-bold text-[#0A1628]">€{money(quotation?.finalPrice)}</p></>}{wc&&wc?.priceChanged?<p className="mt-1 text-sm text-slate-500">Previous: <span className="line-through">€{money(wc?.previousPrice)}</span> → <span className="font-semibold text-[#0A1628]">€{money(wc?.currentPrice)}</span></p>:null}<div className="mt-4 grid gap-2 border-t border-slate-100 pt-4 text-sm">{!multi&&quotation?.serviceLabel?<div className="flex justify-between"><span className="text-slate-500">Service</span><span className="font-semibold text-[#0A1628]">{quotation?.serviceLabel}</span></div>:null}{!multi&&quotation?.finalTransitTime?<div className="flex justify-between"><span className="text-slate-500">Transit time</span><span className="font-semibold text-[#0A1628]">{quotation?.finalTransitTime}</span></div>:null}{quotation?.validUntil?<div className="flex justify-between"><span className="text-slate-500">Valid until</span><span className="font-semibold text-[#0A1628]">{String(quotation?.validUntil).slice(0,10)}</span></div>:null}</div>{(wc&&(wc?.serviceChanged||wc?.transitChanged))?<div className="mt-4 rounded-lg bg-blue-50 p-3 text-xs text-blue-900"><p className="font-semibold">What changed</p>{wc?.serviceChanged?<p className="mt-1">Service: {wc?.previousService||'—'} → {wc?.currentService||'—'}</p>:null}{wc?.transitChanged?<p className="mt-1">Transit: {wc?.previousTransit||'—'} → {wc?.currentTransit||'—'}</p>:null}</div>:null}{quotation?.includedServices?<div className="mt-4"><p className="label">Included</p><p className="text-sm text-slate-600">{quotation?.includedServices}</p></div>:null}{quotation?.excludedServices?<div className="mt-3"><p className="label">Not included</p><p className="text-sm text-slate-600">{quotation?.excludedServices}</p></div>:null}<p className="mt-4 text-sm leading-6 text-slate-600">{quotation?.notes ?? 'Reviewed by the ForwardOne logistics team.'}</p>{expired?<div className="mt-6 rounded-lg border border-rose-200 bg-rose-50 p-4"><p className="flex items-center gap-2 text-sm font-semibold text-rose-800"><AlertTriangle className="h-4 w-4"/> This quotation has expired</p><p className="mt-1 text-xs leading-5 text-rose-700">This quotation is no longer valid. You can request an updated quote from our team.</p><button disabled={deciding} onClick={()=>onRequestUpdate(quote?.id ?? '')} className="btn-primary mt-3 w-full px-3 disabled:opacity-60"><ArrowRight className="h-4 w-4"/> Request Updated Quote</button></div>:decidable?<div className="mt-6 grid grid-cols-2 gap-2"><button disabled={deciding} onClick={()=>onDecide(quote?.id ?? '','REJECTED')} className="btn-secondary px-3 disabled:opacity-60"><XCircle className="h-4 w-4"/> {needsReview?'Decline update':'Reject'}</button><button disabled={deciding} onClick={()=>onDecide(quote?.id ?? '','ACCEPTED',pick||null)} className="btn-primary px-3 disabled:opacity-60">{deciding?<Loader2 className="h-4 w-4 animate-spin"/>:<CheckCircle2 className="h-4 w-4"/>} {multi?'Accept selected':needsReview?'Accept update':'Accept'}</button></div>:null}</div>:<div className="mt-5 rounded-lg bg-blue-50 p-4 text-sm text-blue-800"><Clock3 className="mb-2 h-5 w-5" />Our team is reviewing service options. No price is shown until an administrator approves it.</div>}</div>{history.length>1?<div className="rounded-xl bg-white p-6 shadow-[var(--shadow-md)]"><h3 className="font-bold text-[#0A1628]">Quotation history</h3><div className="mt-4 space-y-2">{history.map((h:any)=><div key={h?.id ?? h?.versionNumber} className="flex items-center justify-between rounded-lg bg-slate-50 p-3 text-sm"><div><p className="font-semibold text-[#0A1628]">Version {h?.versionNumber}</p><p className="text-xs text-slate-500">{String(h?.sentAt ?? h?.createdAt ?? '').slice(0,10)} · {h?.serviceLabel ?? '—'}{h?.finalTransitTime?` · ${h?.finalTransitTime}`:''}</p></div><div className="text-right"><p className="font-semibold text-[#0A1628]">€{money(h?.finalPrice)}</p><p className="text-xs text-slate-500">{h?.status==='ACCEPTED'?'Accepted':h?.status==='REJECTED'?'Declined':'Sent'}</p></div></div>)}</div></div>:null}<div className="rounded-xl bg-[#0A1628] p-5 text-white"><ShieldCheck className="h-5 w-5 text-green-400"/><p className="mt-3 text-sm font-semibold">Manual approval protected</p><p className="mt-1 text-xs leading-5 text-slate-400">Every price includes an operator review before it reaches your account.</p></div></aside></div>}
function ShipmentsList({shipments,base}:{shipments:Shipment[];base:string}){return <div className="grid gap-4"><div><p className="section-kicker">Shipment activity</p><h2 className="text-2xl font-bold text-[#0A1628]">Active and past shipments</h2></div>{shipments?.map?.((s:Shipment)=><Link key={s?.id ?? ''} href={`${base}/shipments/${s?.id ?? ''}`} aria-label={`View tracking for ${s?.trackingNumber ?? 'shipment'}`} className="group block rounded-xl bg-white p-5 shadow-[var(--shadow-sm)] transition hover:shadow-[var(--shadow-md)] hover:ring-1 hover:ring-green-200 focus:outline-none focus-visible:ring-2 focus-visible:ring-green-500 active:scale-[0.99]"><div className="flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between"><div className="flex items-start gap-3"><span className="flex h-10 w-10 shrink-0 items-center justify-center rounded-lg bg-green-50"><Truck className="h-5 w-5 text-green-600"/></span><div className="min-w-0"><p className="font-mono text-sm font-bold text-green-700 underline-offset-2 group-hover:underline">{s?.trackingNumber ?? ''}</p><p className="mt-1 break-words text-sm text-slate-600">{s?.origin ?? ''} → {s?.destination ?? ''}</p><p className="mt-1 break-words text-xs text-slate-400">{customerServiceLabel(s?.carrier)} · {s?.quote?.reference ?? ''}</p></div></div><div className="flex items-center justify-between gap-3 sm:flex-col sm:items-end sm:justify-center"><Status value={s?.status ?? ''}/><span className="flex items-center gap-1 text-xs font-semibold text-green-700"><span className="group-hover:underline">View tracking</span><ArrowRight className="h-3.5 w-3.5 transition group-hover:translate-x-0.5"/></span></div></div></Link>) ?? null}{(shipments?.length ?? 0)===0?<Empty text="No shipments yet. Accepted quotations will appear here once booked."/>:null}</div>}
function shipStatusLabel(value:string){const map:Record<string,string>={BOOKED:'Booking confirmed',PICKUP_SCHEDULED:'Collection scheduled',PICKUP_PENDING:'Awaiting collection',PICKED_UP:'Collected',COLLECTED:'Collected',IN_TRANSIT:'In transit',ARRIVED_AT_DESTINATION:'Arrived in destination country',CUSTOMS_CLEARANCE:'Customs clearance in progress',CUSTOMS_HOLD:'Customs clearance in progress',OUT_FOR_DELIVERY:'Out for delivery',DELIVERED:'Delivered',FINANCIALLY_CLOSED:'Delivered',ON_HOLD:'On hold',EXCEPTION:'Delay — we are on it',CANCELLED:'Cancelled',RETURN_IN_PROGRESS:'Return in progress',RETURNED:'Returned to sender',LOST:'Under investigation',DAMAGED:'Under review'};return map[value ?? '']??format(value ?? '')}
function ShipmentDetail({shipment,base,reload}:{shipment:Shipment;base:string;reload:()=>Promise<void>}){const [busy,setBusy]=useState(false);const [showCancel,setShowCancel]=useState(false);const backLink=<Link href={`${base}/shipments`} className="inline-flex w-fit items-center gap-1 text-sm font-semibold text-slate-600 transition hover:text-[#0A1628]"><ArrowLeft className="h-4 w-4"/> Back to shipments</Link>;if(!shipment)return <div className="grid gap-4">{backLink}<Empty text="Shipment not found. It may not exist or you may not have access to it."/></div>;const events:any[]=Array.isArray(shipment?.trackingEvents)?shipment?.trackingEvents:[];const status=shipment?.status ?? '';const order=['BOOKED','PICKUP_SCHEDULED','PICKED_UP','IN_TRANSIT','CUSTOMS_CLEARANCE','OUT_FOR_DELIVERY','DELIVERED'];const currentRank=order.indexOf(status);const hasCustomsEvent=events.some((e:any)=>e?.status==='CUSTOMS_CLEARANCE'||e?.status==='CUSTOMS_HOLD');const needsCustoms=['IMPORT','EXPORT'].includes(shipment?.quote?.direction ?? '')||hasCustomsEvent||status==='CUSTOMS_CLEARANCE';const customsAction=status==='CUSTOMS_HOLD'||events.some((e:any)=>e?.status==='CUSTOMS_HOLD');const exception=status==='EXCEPTION';const delivered=status==='DELIVERED'||status==='FINANCIALLY_CLOSED';const cancelled=status==='CANCELLED'||status==='RETURNED';const adjustments:any[]=Array.isArray(shipment?.adjustments)?shipment?.adjustments:[];const pendingCharges=adjustments.filter((a:any)=>a?.requiresCustomerApproval&&a?.customerApprovalStatus==='PENDING');const decidedCharges=adjustments.filter((a:any)=>a?.customerApprovalStatus&&a?.customerApprovalStatus!=='PENDING');const canRequestCancel=!['DELIVERED','FINANCIALLY_CLOSED','CANCELLED','RETURNED','RETURN_IN_PROGRESS','LOST','DAMAGED'].includes(status);const podUrl=shipment?.podPath ?? '';async function approveCharge(adjustmentId:string,decision:'APPROVE'|'REJECT'){if(busy)return;setBusy(true);try{const r=await fetch(`/api/shipments/${shipment?.id ?? ''}/adjustment`,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({adjustmentId,decision})});const d=await r?.json?.().catch?.(()=>({})) ?? {};if(!r?.ok)throw new Error(d?.error ?? 'Unable to record your decision.');toast?.success?.(decision==='APPROVE'?'Charge approved — thank you.':'Charge declined.');await reload()}catch(e:unknown){console.error(e);toast?.error?.(e instanceof Error?e?.message ?? 'Unable to record your decision.':'Unable to record your decision.')}finally{setBusy(false)}}async function submitCancel(event:React.FormEvent<HTMLFormElement>){event?.preventDefault?.();if(busy)return;const form=new FormData(event?.currentTarget);const reason=String(form?.get?.('reason') ?? '');setBusy(true);try{const r=await fetch(`/api/shipments/${shipment?.id ?? ''}/cancel-request`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({reason})});const d=await r?.json?.().catch?.(()=>({})) ?? {};if(!r?.ok)throw new Error(d?.error ?? 'Unable to submit request.');toast?.success?.(d?.message ?? 'Cancellation request received.');setShowCancel(false);await reload()}catch(e:unknown){console.error(e);toast?.error?.(e instanceof Error?e?.message ?? 'Unable to submit request.':'Unable to submit request.')}finally{setBusy(false)}}const lastReachedIndexBase=[{label:'Pickup scheduled',threshold:0,match:['BOOKED','PICKUP_SCHEDULED']},{label:'Collected',threshold:2,match:['PICKED_UP']},{label:'In transit',threshold:3,match:['IN_TRANSIT']},{label:'Customs clearance',threshold:4,match:['CUSTOMS_CLEARANCE','CUSTOMS_HOLD'],customs:true},{label:'Out for delivery',threshold:5,match:['OUT_FOR_DELIVERY']},{label:'Delivered',threshold:6,match:['DELIVERED']}];const steps=lastReachedIndexBase.filter((s:any)=>!s.customs||needsCustoms);const lastReachedIndex=steps.reduce((acc:number,st:any,i:number)=>currentRank>=st.threshold?i:acc,-1);const evFor=(m:string[])=>events.find((e:any)=>m.includes(e?.status));const lastEvent=events?.[0] ?? null;const lastUpdate=String(lastEvent?.timestamp ?? shipment?.updatedAt ?? '');const statusColor=delivered?'bg-green-50 text-green-700':exception||cancelled||customsAction?'bg-red-50 text-red-700':status==='CUSTOMS_CLEARANCE'?'bg-amber-50 text-amber-700':'bg-blue-50 text-blue-700';return <div className="grid gap-6">{backLink}<section className="rounded-xl bg-white p-6 shadow-[var(--shadow-md)]"><div className="flex flex-col gap-5 sm:flex-row sm:items-start sm:justify-between"><div className="min-w-0"><span className={`status-badge ${statusColor}`}>{shipStatusLabel(status)}</span><h2 className="mt-3 break-words font-mono text-xl font-bold text-[#0A1628]">{shipment?.trackingNumber ?? ''}</h2><p className="mt-1 break-words text-sm text-slate-500">Reference {shipment?.reference ?? shipment?.quote?.reference ?? '—'} · {shipment?.customerServiceName || customerServiceLabel(shipment?.carrier)}</p>{lastUpdate?<p className="mt-1 text-xs text-slate-400">Last update {lastUpdate.slice(0,16).replace('T',' ')} UTC</p>:null}</div><span className="flex h-12 w-12 shrink-0 items-center justify-center rounded-lg bg-green-50"><Truck className="h-6 w-6 text-green-600"/></span></div><div className="mt-6 grid gap-4 rounded-lg bg-slate-50 p-4 sm:grid-cols-[1fr_auto_1fr]"><Info label="Origin" value={shipment?.origin ?? '—'}/><div className="hidden items-center text-slate-400 sm:flex">→</div><Info label="Destination" value={shipment?.destination ?? '—'}/></div><div className="mt-4 grid gap-4 sm:grid-cols-2"><Info label="Service" value={shipment?.customerServiceName || customerServiceLabel(shipment?.carrier) || '—'}/><Info label="Current status" value={shipStatusLabel(status)}/><Info label="Tracking number" value={shipment?.trackingNumber ?? '—'}/>{shipment?.awbNumber?<Info label="AWB" value={shipment?.awbNumber}/>:null}</div></section>{pendingCharges.length>0?<div className="rounded-xl border-2 border-amber-400 bg-amber-50 p-5"><div className="flex items-start gap-3"><AlertTriangle className="mt-0.5 h-5 w-5 shrink-0 text-amber-600"/><div className="min-w-0 flex-1"><p className="text-sm font-bold text-amber-900">Approval needed — additional charge</p><p className="mt-1 text-sm text-amber-800">An extra charge applies to this shipment. Please review and approve so we can continue.</p><div className="mt-4 grid gap-3">{pendingCharges.map((a:any)=><div key={a?.id ?? ''} className="rounded-lg border border-amber-200 bg-white p-4"><div className="flex flex-wrap items-start justify-between gap-2"><div className="min-w-0"><p className="font-semibold text-[#0A1628]">{format(a?.adjustmentType) || 'Additional charge'}</p>{a?.customerReason||a?.description?<p className="mt-1 break-words text-sm text-slate-600">{a?.customerReason || a?.description}</p>:null}</div><p className="shrink-0 text-lg font-bold text-[#0A1628]">+{a?.currency==='EUR'?'€':''}{money(a?.customerSellingAdjustment)}</p></div><div className="mt-3 grid grid-cols-2 gap-2"><button disabled={busy} onClick={()=>approveCharge(a?.id ?? '','REJECT')} className="btn-secondary px-3 disabled:opacity-60"><XCircle className="h-4 w-4"/> Decline</button><button disabled={busy} onClick={()=>approveCharge(a?.id ?? '','APPROVE')} className="btn-primary px-3 disabled:opacity-60">{busy?<Loader2 className="h-4 w-4 animate-spin"/>:<CheckCircle2 className="h-4 w-4"/>} Approve</button></div></div>)}</div></div></div></div>:null}{shipment?.actionRequired&&pendingCharges.length===0&&!customsAction?<div className="flex items-start gap-3 rounded-xl border border-amber-300 bg-amber-50 p-4"><AlertTriangle className="mt-0.5 h-5 w-5 shrink-0 text-amber-600"/><div className="min-w-0"><p className="text-sm font-bold text-amber-900">Action required</p><p className="mt-1 break-words text-sm text-amber-800">{shipment?.actionMessage || 'We need something from you to continue with this shipment. Please contact our team.'}</p><Link href={`${base}/support`} className="btn-primary mt-3 inline-flex h-9 items-center text-xs">Contact us</Link></div></div>:null}{customsAction?<div className="flex items-start gap-3 rounded-xl border border-amber-300 bg-amber-50 p-4"><AlertTriangle className="mt-0.5 h-5 w-5 shrink-0 text-amber-600"/><div className="min-w-0"><p className="text-sm font-bold text-amber-900">Action required — Customs needs additional information</p><p className="mt-1 text-sm text-amber-800">{shipment?.actionMessage || 'Customs authorities need more information before your shipment can clear. Please provide the requested details so delivery can continue.'}</p><Link href={`${base}/support`} className="btn-primary mt-3 inline-flex h-9 items-center text-xs">Provide information</Link></div></div>:null}{exception&&!customsAction?<div className="flex items-start gap-3 rounded-xl border border-red-300 bg-red-50 p-4"><AlertTriangle className="mt-0.5 h-5 w-5 shrink-0 text-red-600"/><div className="min-w-0"><p className="text-sm font-bold text-red-900">This shipment needs attention</p><p className="mt-1 break-words text-sm text-red-800">{lastEvent?.description || 'There is an exception with your shipment. Our team is reviewing it — contact support if you need an update.'}</p></div></div>:null}{cancelled?<div className="flex items-start gap-3 rounded-xl border border-slate-300 bg-slate-50 p-4"><XCircle className="mt-0.5 h-5 w-5 shrink-0 text-slate-500"/><div className="min-w-0"><p className="text-sm font-bold text-slate-700">{status==='RETURNED'?'This shipment was returned to sender':'This shipment was cancelled'}</p><p className="mt-1 break-words text-sm text-slate-600">{lastEvent?.description || 'This shipment is no longer active.'}</p></div></div>:null}{delivered?<div className="flex items-start gap-3 rounded-xl border border-green-300 bg-green-50 p-4"><PackageCheck className="mt-0.5 h-5 w-5 shrink-0 text-green-600"/><div className="min-w-0 flex-1"><p className="text-sm font-bold text-green-900">Delivered</p><p className="mt-1 break-words text-sm text-green-800">Your shipment has been delivered. Thank you for shipping with ForwardOne.</p>{podUrl?<a href={podUrl} target="_blank" rel="noopener noreferrer" className="btn-secondary mt-3 inline-flex h-9 items-center text-xs"><Download className="h-3.5 w-3.5"/> Download proof of delivery</a>:null}</div></div>:null}<section className="rounded-xl bg-white p-6 shadow-[var(--shadow-sm)]"><h3 className="mb-6 font-bold text-[#0A1628]">Tracking timeline</h3>{cancelled?<p className="text-sm text-slate-500">Tracking is unavailable for cancelled shipments.</p>:<div className="relative ml-3 border-l-2 border-slate-200 pl-7">{steps.map((st:any,i:number)=>{const reached=currentRank>=st.threshold;const isCurrent=reached&&i===lastReachedIndex;const ev=evFor(st.match);return <div key={st.label} className="relative pb-8 last:pb-0"><span className={`absolute -left-[38px] top-0 flex h-5 w-5 items-center justify-center rounded-full ${reached?'bg-green-600 text-white':'bg-white text-slate-300 ring-2 ring-slate-200'}`}>{reached?<CheckCircle2 className="h-3.5 w-3.5"/>:<Circle className="h-2.5 w-2.5"/>}</span><div className="flex flex-col gap-1 sm:flex-row sm:items-start sm:justify-between"><div className="min-w-0"><p className={`text-sm font-bold ${reached?'text-[#0A1628]':'text-slate-400'}`}>{st.label}{isCurrent?<span className="ml-2 rounded bg-green-100 px-1.5 py-0.5 text-[10px] font-semibold text-green-700">Current</span>:null}</p>{ev?.description?<p className="mt-1 break-words text-sm text-slate-600">{ev?.description}</p>:null}{ev?.location?<p className="mt-1 flex items-center gap-1 text-xs text-slate-400"><MapPin className="h-3 w-3 shrink-0"/>{ev?.location}</p>:null}</div>{ev?.timestamp?<time className="shrink-0 text-xs text-slate-400">{String(ev?.timestamp).slice(0,16).replace('T',' ')} UTC</time>:null}</div></div>})}</div>}</section>{decidedCharges.length>0?<section className="rounded-xl bg-white p-6 shadow-[var(--shadow-sm)]"><h3 className="mb-4 font-bold text-[#0A1628]">Additional charges</h3><div className="grid gap-2">{decidedCharges.map((a:any)=><div key={a?.id ?? ''} className="flex items-center justify-between rounded-lg bg-slate-50 p-3 text-sm"><div className="min-w-0"><p className="font-semibold text-[#0A1628]">{format(a?.adjustmentType) || 'Charge'}</p>{a?.customerReason||a?.description?<p className="mt-0.5 break-words text-xs text-slate-500">{a?.customerReason || a?.description}</p>:null}</div><div className="shrink-0 text-right"><p className="font-bold text-[#0A1628]">+{a?.currency==='EUR'?'€':''}{money(a?.customerSellingAdjustment)}</p><p className={`text-xs font-semibold ${a?.customerApprovalStatus==='APPROVED'?'text-green-700':'text-slate-500'}`}>{a?.customerApprovalStatus==='APPROVED'?'Approved':'Declined'}</p></div></div>)}</div></section>:null}<CustomerDocuments shipmentId={shipment?.id ?? ''}/><CustomerInvoices reference={shipment?.reference ?? ''}/>{canRequestCancel?<section className="rounded-xl border border-slate-200 bg-white p-6 shadow-[var(--shadow-sm)]">{!showCancel?<div className="flex flex-wrap items-center justify-between gap-3"><div className="min-w-0"><p className="font-bold text-[#0A1628]">Need to cancel this shipment?</p><p className="mt-1 text-sm text-slate-500">You can request cancellation. Our team will confirm whether it's still possible.</p></div><button onClick={()=>setShowCancel(true)} className="btn-secondary shrink-0 px-3"><XCircle className="h-4 w-4"/> Request cancellation</button></div>:<form onSubmit={submitCancel}><p className="font-bold text-[#0A1628]">Request cancellation</p><p className="mt-1 text-sm text-slate-500">Tell us why you'd like to cancel. This is a request — our team will review and confirm.</p><textarea name="reason" className="field mt-3 min-h-24 py-3" placeholder="Reason for cancellation (optional)"/><div className="mt-3 flex gap-2"><button type="button" onClick={()=>setShowCancel(false)} className="btn-secondary flex-1">Keep shipment</button><button disabled={busy} className="btn-primary flex-1 disabled:opacity-60">{busy?<Loader2 className="h-4 w-4 animate-spin"/>:<Send className="h-4 w-4"/>} Submit request</button></div></form>}</section>:null}</div>}
function AddressBook({addresses,editing,setEditing,reload,enhanced}:{addresses:Address[];editing:Address|null;setEditing:(a:Address|null)=>void;reload:()=>Promise<void>;enhanced:boolean}){async function save(event:React.FormEvent<HTMLFormElement>){event?.preventDefault?.();const form=new FormData(event?.currentTarget);const body=Object.fromEntries(form?.entries?.() ?? []);try{const response=await fetch(editing?`/api/addresses/${editing?.id ?? ''}`:'/api/addresses',{method:editing?'PATCH':'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...body,isFavorite:Boolean(form?.get?.('isFavorite'))})});const data=await response?.json?.().catch?.(()=>({})) ?? {};if(!response?.ok)throw new Error(data?.error ?? 'Unable to save address.');toast?.success?.('Address saved.');setEditing(null);(event?.currentTarget as HTMLFormElement)?.reset?.();await reload()}catch(error:unknown){console.error(error);toast?.error?.(error instanceof Error?error?.message ?? 'Unable to save address.':'Unable to save address.')}}async function remove(id:string){try{await fetch(`/api/addresses/${id}`,{method:'DELETE'});toast?.success?.('Address removed.');await reload()}catch(error:unknown){console.error(error)}}async function favorite(a:Address){try{await fetch(`/api/addresses/${a?.id ?? ''}`,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({isFavorite:!a?.isFavorite})});await reload()}catch(error:unknown){console.error(error)}}return <div className="grid gap-5 lg:grid-cols-[1fr_390px]"><section><p className="section-kicker">{enhanced?'Enhanced business address book':'Saved addresses'}</p><h2 className="text-2xl font-bold text-[#0A1628]">Reusable pickup and delivery points</h2><div className="mt-6 grid gap-4 sm:grid-cols-2">{addresses?.map?.((a:Address)=><article key={a?.id ?? ''} className="rounded-xl bg-white p-5 shadow-[var(--shadow-sm)]"><div className="flex justify-between gap-3"><div className="flex gap-2"><MapPin className="mt-0.5 h-4 w-4 text-green-600"/><div><p className="font-bold text-[#0A1628]">{a?.label ?? ''}</p><p className="mt-1 text-sm text-slate-600">{a?.name ?? ''}{a?.company?` · ${a?.company}`:''}</p></div></div><button onClick={()=>favorite(a)} aria-label="Toggle favourite"><Star className={`h-4 w-4 ${a?.isFavorite?'fill-amber-400 text-amber-400':'text-slate-300'}`}/></button></div><p className="mt-4 text-sm leading-6 text-slate-500">{a?.addressLine1 ?? ''}<br/>{a?.city ?? ''}, {a?.country ?? ''}</p><div className="mt-4 flex gap-2"><button onClick={()=>setEditing(a)} className="btn-secondary min-h-9 flex-1 px-3 py-1"><Pencil className="h-3.5 w-3.5"/> Edit</button><button onClick={()=>remove(a?.id ?? '')} className="rounded-lg bg-red-50 px-3 text-red-600 hover:bg-red-100" aria-label="Delete address"><Trash2 className="h-4 w-4"/></button></div></article>) ?? null}{(addresses?.length ?? 0)===0?<Empty text="No saved addresses yet."/>:null}</div></section><form key={editing?.id ?? 'new'} onSubmit={save} className="h-fit rounded-xl bg-white p-5 shadow-[var(--shadow-md)]"><h3 className="font-bold text-[#0A1628]">{editing?'Edit address':'Add address'}</h3><div className="mt-5 grid gap-3 sm:grid-cols-2">{[{n:'label',l:'Label'},{n:'name',l:'Contact name'},{n:'company',l:'Company'},{n:'addressLine1',l:'Address',wide:true},{n:'country',l:'Country'},{n:'city',l:'City'},{n:'phone',l:'Phone'},{n:'email',l:'Email',t:'email'}]?.map?.((f:any)=><label key={f?.n ?? ''} className={f?.wide?'sm:col-span-2':''}><span className="label">{f?.l ?? ''}</span><input name={f?.n ?? ''} type={f?.t ?? 'text'} defaultValue={editing?.[f?.n] ?? ''} className="field" required={f?.n!=='company'}/></label>) ?? null}<label className="flex items-center gap-2 text-sm sm:col-span-2"><input name="isFavorite" type="checkbox" defaultChecked={editing?.isFavorite ?? false} className="accent-green-600"/> Mark as favourite</label></div><div className="mt-5 flex gap-2">{editing?<button type="button" onClick={()=>setEditing(null)} className="btn-secondary flex-1">Cancel</button>:null}<button className="btn-primary flex-1"><Plus className="h-4 w-4"/> Save</button></div></form></div>}
function SupportDesk({tickets,reload}:{tickets:Ticket[];reload:()=>Promise<void>}){async function submit(event:React.FormEvent<HTMLFormElement>){event?.preventDefault?.();const form=new FormData(event?.currentTarget);try{const response=await fetch('/api/support',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(Object.fromEntries(form?.entries?.() ?? []))});if(!response?.ok)throw new Error('Unable to open ticket.');toast?.success?.('Support ticket opened.');(event?.currentTarget as HTMLFormElement)?.reset?.();await reload()}catch(error:unknown){console.error(error);toast?.error?.('Unable to open ticket.')}}return <div className="grid gap-5 lg:grid-cols-[1fr_390px]"><section><p className="section-kicker">Help desk</p><h2 className="text-2xl font-bold text-[#0A1628]">Your support history</h2><div className="mt-6 grid gap-3">{tickets?.map?.((t:Ticket)=><article key={t?.id ?? ''} className="rounded-xl bg-white p-5 shadow-[var(--shadow-sm)]"><div className="flex justify-between gap-3"><h3 className="font-bold text-[#0A1628]">{t?.subject ?? ''}</h3><Status value={t?.status ?? ''}/></div><p className="mt-3 text-sm text-slate-600">{t?.message ?? ''}</p>{t?.response?<div className="mt-4 rounded-lg bg-green-50 p-3 text-sm text-green-800"><strong>ForwardOne:</strong> {t?.response ?? ''}</div>:null}</article>) ?? null}{(tickets?.length ?? 0)===0?<Empty text="No support tickets yet."/>:null}</div></section><form onSubmit={submit} className="h-fit rounded-xl bg-white p-5 shadow-[var(--shadow-md)]"><h3 className="font-bold text-[#0A1628]">Open a support ticket</h3><label className="mt-5 block"><span className="label">Subject</span><input name="subject" className="field" required/></label><label className="mt-3 block"><span className="label">Message</span><textarea name="message" className="field min-h-32 py-3" required/></label><p className="mt-3 text-xs leading-5 text-slate-400">Your message is stored securely with your account so the operations team can respond.</p><button className="btn-primary mt-5 w-full"><Send className="h-4 w-4"/> Send request</button></form></div>}
function Documents({quotes}:{quotes:Quote[]}){const files=quotes?.flatMap?.((q:Quote)=>(q?.files ?? []).map((f:any)=>({...f,reference:q?.reference}))) ?? [];async function download(id:string){try{const response=await fetch(`/api/files/${id}`);const data=await response?.json?.().catch?.(()=>({})) ?? {};if(!response?.ok||!data?.file?.url)throw new Error(data?.error ?? 'Unable to access file.');const anchor=document?.createElement?.('a');if(!anchor)return;anchor.href=data?.file?.url ?? '';anchor.download=data?.file?.fileName ?? 'document';document?.body?.appendChild?.(anchor);anchor?.click?.();anchor?.remove?.()}catch(error:unknown){console.error(error);toast?.error?.(error instanceof Error?error?.message ?? 'Unable to download file.':'Unable to download file.')}}return <div><p className="section-kicker">Document workspace</p><h2 className="text-2xl font-bold text-[#0A1628]">Saved shipment documents</h2><div className="mt-6 grid gap-4 sm:grid-cols-2 lg:grid-cols-3">{files?.map?.((f:any)=><article key={f?.id ?? ''} className="rounded-xl bg-white p-5 shadow-[var(--shadow-sm)]"><FileText className="h-6 w-6 text-green-600"/><p className="mt-4 truncate font-bold text-[#0A1628]">{f?.fileName ?? ''}</p><p className="mt-1 text-xs text-slate-500">{format(f?.fileType)} · {f?.reference ?? ''}</p><div className="mt-4 grid grid-cols-2 gap-2"><button onClick={()=>download(f?.id ?? '')} className="btn-secondary h-9 px-2 text-xs"><Download className="h-3.5 w-3.5"/> Download</button><Link href={`/quote/new?reuseFile=${encodeURIComponent(f?.id ?? '')}`} className="btn-primary h-9 px-2 text-xs"><FileText className="h-3.5 w-3.5"/> Reuse</Link></div></article>) ?? null}{(files?.length ?? 0)===0?<Empty text="No documents uploaded yet."/>:null}</div></div>}
function CustomerDocuments({shipmentId}:{shipmentId:string}){const [docs,setDocs]=useState<any[]>([]);const [loading,setLoading]=useState(true);const [dl,setDl]=useState<string>('');useEffect(()=>{let alive=true;(async()=>{if(!shipmentId){setLoading(false);return}try{const r=await fetch(`/api/shipments/${shipmentId}/documents`);const d=await r?.json?.().catch?.(()=>({})) ?? {};if(alive)setDocs(Array.isArray(d?.documents)?d.documents:[])}catch(e){console.error(e)}finally{if(alive)setLoading(false)}})();return()=>{alive=false}},[shipmentId]);async function download(docId:string){if(dl)return;setDl(docId);try{const r=await fetch(`/api/shipments/${shipmentId}/documents/${docId}`);const d=await r?.json?.().catch?.(()=>({})) ?? {};if(!r?.ok||!d?.url)throw new Error(d?.error ?? 'Unable to download document.');const a=document.createElement('a');a.href=d.url;a.download=d?.fileName ?? '';a.target='_blank';a.rel='noopener noreferrer';document.body.appendChild(a);a.click();a.remove()}catch(e:unknown){console.error(e);toast?.error?.(e instanceof Error?e?.message ?? 'Unable to download document.':'Unable to download document.')}finally{setDl('')}}if(loading||docs.length===0)return null;return <section className="rounded-xl bg-white p-6 shadow-[var(--shadow-sm)]"><h3 className="mb-4 font-bold text-[#0A1628]">Shipment documents</h3><div className="grid gap-2">{docs.map((f:any)=><div key={f?.id ?? ''} className="flex items-center justify-between gap-3 rounded-lg bg-slate-50 p-3"><div className="flex min-w-0 items-center gap-3"><span className="flex h-9 w-9 shrink-0 items-center justify-center rounded-lg bg-white"><FileText className="h-4 w-4 text-slate-500"/></span><div className="min-w-0"><p className="truncate text-sm font-semibold text-[#0A1628]">{f?.fileName ?? 'Document'}</p><p className="text-xs text-slate-500">{documentCategoryLabel(f?.category)}</p></div></div><button disabled={dl===f?.id} onClick={()=>download(f?.id ?? '')} className="btn-secondary shrink-0 px-3 disabled:opacity-60">{dl===f?.id?<Loader2 className="h-4 w-4 animate-spin"/>:<Download className="h-4 w-4"/>} Download</button></div>)}</div></section>}
function CustomerInvoices({reference}:{reference:string}){const [invoices,setInvoices]=useState<any[]>([]);const [loading,setLoading]=useState(true);useEffect(()=>{let alive=true;(async()=>{if(!reference){setLoading(false);return}try{const r=await fetch('/api/invoices');const d=await r?.json?.().catch?.(()=>({})) ?? {};const all=Array.isArray(d?.invoices)?d.invoices:(Array.isArray(d)?d:[]);if(alive)setInvoices(all.filter((i:any)=>i?.shipmentReference===reference))}catch(e){console.error(e)}finally{if(alive)setLoading(false)}})();return()=>{alive=false}},[reference]);if(loading||invoices.length===0)return null;return <section className="rounded-xl bg-white p-6 shadow-[var(--shadow-sm)]"><h3 className="mb-4 font-bold text-[#0A1628]">Invoice</h3><div className="grid gap-4">{invoices.map((inv:any)=>{const ccy=inv?.currency ?? 'EUR';const charges:any[]=Array.isArray(inv?.charges)?inv.charges:[];const fin=String(inv?.finalizedAt ?? '').slice(0,10);return <div key={inv?.id ?? ''} className="rounded-lg border border-slate-200 p-4"><div className="flex flex-wrap items-start justify-between gap-2"><div className="min-w-0"><p className="font-mono text-sm font-bold text-[#0A1628]">{inv?.reference ?? '—'}</p>{inv?.serviceName?<p className="mt-0.5 text-sm text-slate-600">{inv?.serviceName}</p>:null}{fin?<p className="mt-0.5 text-xs text-slate-400">Issued {fin}</p>:null}</div><span className="status-badge bg-green-50 text-green-700">Finalized</span></div><div className="mt-4 grid gap-1.5 border-t border-slate-100 pt-3 text-sm"><div className="flex items-center justify-between"><span className="text-slate-600">Service charge</span><span className="font-semibold text-[#0A1628]">{sym(ccy)}{money(inv?.sellingPrice)}</span></div>{charges.map((c:any,i:number)=><div key={i} className="flex items-center justify-between"><span className="break-words text-slate-600">{c?.description ?? c?.label ?? 'Charge'}</span><span className="font-semibold text-[#0A1628]">{sym(ccy)}{money(c?.amount)}</span></div>)}<div className="mt-1 flex items-center justify-between border-t border-slate-100 pt-2"><span className="font-bold text-[#0A1628]">Total</span><span className="font-bold text-[#0A1628]">{sym(ccy)}{money(inv?.total)}</span></div></div><div className="mt-4 border-t border-slate-100 pt-3"><InvoiceActions invoiceId={inv?.id ?? ''} /></div></div>})}</div></section>}
function Empty({text}:{text:string}){return <div className="rounded-xl bg-white p-10 text-center text-sm text-slate-400 shadow-[var(--shadow-sm)]"><Box className="mx-auto mb-3 h-7 w-7 text-slate-300"/>{text ?? ''}</div>}
function Status({value}:{value:string}){const color=value==='DELIVERED'||value==='ACCEPTED'?'bg-green-50 text-green-700':value==='REJECTED'||value==='EXCEPTION'?'bg-red-50 text-red-700':value==='PENDING_REVIEW'||value==='OPEN'?'bg-amber-50 text-amber-700':'bg-blue-50 text-blue-700';return <span className={`status-badge whitespace-nowrap ${color}`}>{format(value)}</span>}
function Info({label,value}:{label:string;value:string}){return <div><p className="label">{label ?? ''}</p><p className="text-sm font-semibold text-[#0A1628]">{value ?? ''}</p></div>}
function Party({title,data}:{title:string;data:any}){return <div><h3 className="mb-3 font-bold text-[#0A1628]">{title ?? ''}</h3><div className="text-sm leading-6 text-slate-600"><p className="font-semibold">{data?.name ?? ''}</p><p>{data?.company ?? ''}</p><p>{data?.address ?? ''}</p><p>{data?.city ?? ''}, {data?.country ?? ''}</p><p>{data?.phone ?? ''}</p><p>{data?.email ?? ''}</p></div></div>}
const format=(value:string)=>String(value ?? '').split?.('_')?.join?.(' ')?.replace?.(/\b\w/g,(c:string)=>c?.toUpperCase?.() ?? c) ?? ''
const money=(value:unknown)=>Number(value ?? 0)?.toFixed?.(2) ?? '0.00'
const sym=(currency?:string)=>({EUR:'€',USD:'$',GBP:'£'} as Record<string,string>)[String(currency ?? 'EUR')] ?? ''
function BookingSteps({quote}:{quote:any}){const accepted=quote?.status==='ACCEPTED'||quote?.status==='BOOKED';const submitted=!!quote?.bookingSubmittedAt;const booked=quote?.status==='BOOKED';const steps=[{label:'Quote',done:true},{label:'Accepted',done:accepted},{label:'Details submitted',done:submitted},{label:'Booking confirmed',done:booked}];return <div className="flex items-center gap-1">{steps.map((s,i)=><div key={i} className="flex flex-1 items-center gap-1"><div className={`flex h-6 w-6 shrink-0 items-center justify-center rounded-full text-[11px] font-bold ${s.done?'bg-green-600 text-white':'bg-slate-200 text-slate-500'}`}>{s.done?<CheckCircle2 className="h-3.5 w-3.5"/>:i+1}</div><span className={`hidden text-[11px] font-semibold sm:inline ${s.done?'text-[#0A1628]':'text-slate-400'}`}>{s.label}</span>{i<steps.length-1?<div className={`h-px flex-1 ${s.done?'bg-green-600':'bg-slate-200'}`}/>:null}</div>)}</div>}
function BookingCta({quote}:{quote:any}){const submitted=!!quote?.bookingSubmittedAt;const needs=!!quote?.needsReapproval;if(quote?.status==='ACCEPTED'&&!submitted){return <div className="rounded-xl border-2 border-green-600 bg-green-50 p-5"><PackageCheck className="h-6 w-6 text-green-700"/><p className="mt-3 font-bold text-[#0A1628]">Next step: complete your booking details</p><p className="mt-1 text-xs leading-5 text-slate-600">We've prefilled everything from your quote. Confirm your pickup, delivery and goods details so we can arrange your shipment.</p><Link href={`/booking/${quote?.id}`} className="btn-primary mt-4 w-full justify-center">Complete Booking Details <ArrowRight className="h-4 w-4"/></Link></div>}if(submitted&&needs){return <div className="rounded-xl border border-amber-300 bg-amber-50 p-5"><Clock3 className="h-6 w-6 text-amber-600"/><p className="mt-3 font-bold text-[#0A1628]">We're reviewing your updated details</p><p className="mt-1 text-xs leading-5 text-amber-900">Some details you submitted may affect your quote. Our team is reviewing them and will confirm your booking shortly.</p></div>}if(submitted&&!needs&&quote?.status!=='BOOKED'){return <div className="rounded-xl border border-green-200 bg-green-50 p-5"><CheckCircle2 className="h-6 w-6 text-green-700"/><p className="mt-3 font-bold text-[#0A1628]">Booking details received</p><p className="mt-1 text-xs leading-5 text-slate-600">Thanks! We're preparing your booking. You'll be notified once it's confirmed.</p><Link href={`/booking/${quote?.id}`} className="btn-secondary mt-4 w-full justify-center">Update details</Link></div>}if(quote?.status==='BOOKED'){return <div className="rounded-xl border border-green-200 bg-green-50 p-5"><PackageCheck className="h-6 w-6 text-green-700"/><p className="mt-3 font-bold text-[#0A1628]">Booking confirmed</p><p className="mt-1 text-xs leading-5 text-slate-600">Your shipment is booked. Track its progress from the Shipments tab.</p></div>}return null}
